describe('View Item Details - CRUD Operations', () => {
  const baseUrl = Cypress.env('BASE_URL') || 'http://localhost:3000';
  const itemsEndpoint = '/api/items';
  const testItemId = '12345';
  const testItem = {
    id: testItemId,
    name: 'Test Item',
    description: 'This is a test item description',
    price: 99.99,
    category: 'Electronics',
    stock: 50,
    createdAt: '2024-01-15T10:30:00Z',
    updatedAt: '2024-01-15T10:30:00Z'
  };

  beforeEach(() => {
    cy.visit(`${baseUrl}`);
    cy.intercept('GET', `${itemsEndpoint}`, {
      statusCode: 200,
      body: {
        items: [testItem, { id: '67890', name: 'Another Item', price: 49.99 }]
      }
    }).as('getItems');
    cy.intercept('GET', `${itemsEndpoint}/${testItemId}`, {
      statusCode: 200,
      body: testItem
    }).as('getItemDetails');
  });

  it('should display item details when clicking on an item from the list', () => {
    cy.wait('@getItems');
    cy.get('[data-testid="item-list"]').should('be.visible');
    cy.get(`[data-testid="item-card-${testItemId}"]`).should('be.visible');
    cy.get(`[data-testid="item-card-${testItemId}"]`).click();
    cy.wait('@getItemDetails');
    cy.get('[data-testid="item-details-container"]').should('be.visible');
    cy.get('[data-testid="item-name"]').should('contain', testItem.name);
    cy.get('[data-testid="item-description"]').should('contain', testItem.description);
    cy.get('[data-testid="item-price"]').should('contain', testItem.price);
    cy.get('[data-testid="item-category"]').should('contain', testItem.category);
    cy.get('[data-testid="item-stock"]').should('contain', testItem.stock);
    cy.url().should('include', `/items/${testItemId}`);
  });

  it('should handle item not found error gracefully', () => {
    cy.intercept('GET', `${itemsEndpoint}/nonexistent`, {
      statusCode: 404,
      body: { error: 'Item not found' }
    }).as('getItemNotFound');
    cy.visit(`${baseUrl}/items/nonexistent`);
    cy.wait('@getItemNotFound');
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Item not found');
    cy.get('[data-testid="back-button"]').should('be.visible');
    cy.get('[data-testid="back-button"]').click();
    cy.url().should('equal', `${baseUrl}/`);
  });

  it('should display loading state while fetching item details', () => {
    cy.intercept('GET', `${itemsEndpoint}/${testItemId}`, (req) => {
      req.reply((res) => {
        res.delay(2000);
      });
    }).as('getItemDetailsDelayed');
    cy.get(`[data-testid="item-card-${testItemId}"]`).click();
    cy.get('[data-testid="loading-spinner"]').should('be.visible');
    cy.wait('@getItemDetailsDelayed');
    cy.get('[data-testid="loading-spinner"]').should('not.exist');
    cy.get('[data-testid="item-details-container"]').should('be.visible');
  });

  it('should display all item details fields with correct data types', () => {
    cy.get(`[data-testid="item-card-${testItemId}"]`).click();
    cy.wait('@getItemDetails');
    cy.get('[data-testid="item-id"]').should('contain', testItemId);
    cy.get('[data-testid="item-price"]').then(($price) => {
      const priceText = $price.text();
      expect(parseFloat(priceText)).to.equal(testItem.price);
    });
    cy.get('[data-testid="item-stock"]').then(($stock) => {
      const stockText = $stock.text();
      expect(parseInt(stockText)).to.equal(testItem.stock);
    });
    cy.get('[data-testid="item-created-date"]').should('be.visible');
    cy.get('[data-testid="item-updated-date"]').should('be.visible');
  });

  it('should allow navigation back to items list from details view', () => {
    cy.get(`[data-testid="item-card-${testItemId}"]`).click();
    cy.wait('@getItemDetails');
    cy.get('[data-testid="item-details-container"]').should('be.visible');
    cy.get('[data-testid="back-button"]').click();
    cy.url().should('equal', `${baseUrl}/`);
    cy.get('[data-testid="item-list"]').should('be.visible');
  });

  it('should handle server error when fetching item details', () => {
    cy.intercept('GET', `${itemsEndpoint}/${testItemId}`, {
      statusCode: 500,
      body: { error: 'Internal server error' }
    }).as('getItemError');
    cy.get(`[data-testid="item-card-${testItemId}"]`).click();
    cy.wait('@getItemError');
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'error');
    cy.get('[data-testid="retry-button"]').should('be.visible');
  });
});
